import { defineConfig, devices } from "@playwright/test";

// Visual tests (tier A): the card in a static harness with fixture data.
// Reference screenshots are per platform: the committed ones are Linux
// (generated by CI, see .github/workflows/tests.yml); local ones from other
// systems stay out of git (.gitignore).
const desktop = { viewport: { width: 1280, height: 900 }, deviceScaleFactor: 1 };
const mobile = { ...devices["Pixel 7"], deviceScaleFactor: 1, defaultBrowserType: "chromium" };

export default defineConfig({
    testDir: "tests/visual",
    testMatch: "**/*.spec.js",
    snapshotPathTemplate: "{testDir}/__screenshots__/{testFileName}/{arg}-{projectName}-{platform}{ext}",
    fullyParallel: true,
    forbidOnly: !!process.env.CI,
    retries: 0,
    reporter: process.env.CI ? [["list"], ["html", { open: "never" }]] : [["list"]],
    expect: {
        toHaveScreenshot: { animations: "disabled", caret: "hide", scale: "css" },
    },
    use: {
        browserName: "chromium",
        timezoneId: "Europe/Paris",
        locale: "en-US",
        trace: "retain-on-failure",
    },
    projects: [
        { name: "desktop-light", use: { ...desktop, colorScheme: "light" } },
        { name: "desktop-dark", use: { ...desktop, colorScheme: "dark" } },
        { name: "mobile-light", use: { ...mobile, colorScheme: "light" } },
        { name: "mobile-dark", use: { ...mobile, colorScheme: "dark" } },
    ],
});
